    'Test the connection' => 'Tester la connexion',
    'Add a calendar' => 'Ajouter un calendrier',
    'Remove this connection? Its calendars and their synced events are removed from Craft. Entries stay, and nothing changes at the provider.' => 'Supprimer cette connexion ? Ses calendriers et leurs événements synchronisés sont supprimés de Craft. Les entrées restent, et rien ne change chez le fournisseur.',
    'All calendars' => 'Tous les calendriers',
