    'Page {page} of {pages}' => 'Page {page} sur {pages}',
    'No events here. They appear after the first sync of a calendar.' => 'Aucun événement ici. Ils apparaissent après la première synchronisation d’un calendrier.',
    'All runs' => 'Toutes les exécutions',
